package __PACKAGE__;

import java.util.LinkedHashMap;
import java.util.Map;

/**
 * Values given to the user parameters of a system for one play (the parameters made in the Sparkle editor:
 * the end of a beam, a speed, a color...). A parameter the system does not have is ignored.
 * Generated by the Sparkle plugin: do not edit, it is written again when the runtime is updated.
 */
public final class SparkleParameters {
    private final Map<String, double[]> values = new LinkedHashMap<>();

    public static SparkleParameters create() {
        return new SparkleParameters();
    }

    /** A number. */
    public SparkleParameters number(String name, double value) {
        return put(name, value, 0.0, 0.0);
    }

    /** A vector, in blocks from the place where the system plays. */
    public SparkleParameters vector(String name, double x, double y, double z) {
        return put(name, x, y, z);
    }

    /** A color, 0xRRGGBB. */
    public SparkleParameters color(String name, int rgb) {
        return put(name, (rgb >> 16 & 255) / 255.0, (rgb >> 8 & 255) / 255.0, (rgb & 255) / 255.0);
    }

    /** Yes or no. */
    public SparkleParameters flag(String name, boolean value) {
        return put(name, value ? 1.0 : 0.0, 0.0, 0.0);
    }

    Map<String, double[]> values() {
        return values;
    }

    private SparkleParameters put(String name, double x, double y, double z) {
        if (name != null && !name.isBlank()) {
            values.put(name.trim(), new double[] { x, y, z });
        }

        return this;
    }
}
